                        + upgrade.artifactId + ") from " + currentVersion + " to " + upgrade.minVersion
                        + " in "
                        + sectionName);
                return true;
            } else {
                context.debug("Property " + propertyName + " version " + currentVersion + " is already >= "
                        + upgrade.minVersion);
            }
        } else {
            context.warning("Property " + propertyName + " not found in POM properties");
